"use strict";
// Writes tests/fixtures/si/atrium-demo.ibs: a synthetic IBIS file written for Atrium's tests.
// Every number comes from the closed-form device below, not from a vendor file, so the file can be
// used freely (CC0 1.0). The V-t waveforms are simulated from the I-V tables with a known raised-
// cosine switching ramp, so a reader that recovers the ramp from two waveforms can be checked.
//   jsc tests/jsc-shim.js -- "$PWD/tests/fixtures/si/make-demo-ibis.cjs" > tests/fixtures/si/atrium-demo.ibs
//   (then delete the SHIM-OK line after [End])
const IB = require("../../../extensions/si/ibis.js"), S = require("../../../extensions/si/solver.js");
const CORNERS = {typ: {vcc: 3.3, ron: 40, isat: 0.06, cc: 3e-12, tr: 0.6e-9}, min: {vcc: 3.0, ron: 55, isat: 0.045, cc: 3.5e-12, tr: 0.8e-9}, max: {vcc: 3.6, ron: 30, isat: 0.08, cc: 2.5e-12, tr: 0.45e-9}};
const f = (x, d = 4) => { const a = Math.abs(x); return a === 0 ? "0" : a >= 1e-3 ? x.toFixed(d + 2).replace(/0+$/, "").replace(/\.$/, "") : (x * 1e3).toFixed(d + 1).replace(/0+$/, "").replace(/\.$/, "") + "m"; };
const fe = x => x.toExponential(4);
const pd = (c, v) => (v >= 0 ? c.isat * Math.tanh(v / (c.ron * c.isat)) : v / c.ron);
const pu = (c, vt) => -pd(c, vt);
// Clamp diode: 3 ohm beyond 0.6 V of forward bias. GND clamp current is negative (out of the pin);
// the POWER clamp table (Vcc - V) is positive (into the pin) for a pin above Vcc.
const clamp = v => (v < -0.6 ? (v + 0.6) / 3 : 0);
const ivRows = (fn, lo, hi, n) => { const out = []; for (let i = 0; i < n; i++) { const v = lo + (hi - lo) * i / (n - 1); out.push("  " + [f(v, 3), ...["typ", "min", "max"].map(k => fe(fn(CORNERS[k], v)))].join("  ")); } return out.join("\n"); };
const ramp = (c, t) => (t <= 0 ? 0 : t >= c.tr ? 1 : 0.5 - 0.5 * Math.cos(Math.PI * t / c.tr));
const T0 = 0.1e-9, N = 101, SPAN = 2e-9;
function wave(rise, vfix) {
  const out = {};
  for (const k of ["typ", "min", "max"]) {
    const c = CORNERS[k];
    const m = {pullup: {v: [-c.vcc, 0, 2 * c.vcc], typ: [], min: [], max: []}};
    // Device: Ku, Kd from the raised cosine; tables evaluated in closed form.
    const ckt = new S.Circuit(), d = ckt.node("die");
    ckt.C(d, -1, c.cc);
    const vf = typeof vfix === "function" ? vfix(c) : vfix;
    ckt.V(d, 50, () => vf);
    ckt.D(d, {i: (v, t) => {
      const r = ramp(c, t - T0), ku = rise ? r : 1 - r, kd = 1 - ku, h = 1e-6;
      const I = x => ku * pu(c, c.vcc - x) + kd * pd(c, x) + clamp(x) - clamp(c.vcc - x);
      return [I(v), (I(v + h) - I(v - h)) / (2 * h)];
    }});
    const r = S.simulate(ckt, {dt: 1e-12, tstop: SPAN, probes: [d]});
    out[k] = Array.from({length: N}, (_, i) => S.at(r.t, r.v[0], SPAN * i / (N - 1)));
  }
  return Array.from({length: N}, (_, i) => "  " + [fe(SPAN * i / (N - 1)), f(out.typ[i], 4), f(out.min[i], 4), f(out.max[i], 4)].join("  ")).join("\n");
}
const wf = (rise, vfix, label) => `[${rise ? "Rising" : "Falling"} Waveform]
R_fixture = 50
V_fixture = ${typeof vfix === "function" ? vfix(CORNERS.typ) : vfix}
V_fixture_min = ${typeof vfix === "function" ? vfix(CORNERS.min) : vfix}
V_fixture_max = ${typeof vfix === "function" ? vfix(CORNERS.max) : vfix}
| time  V(typ)  V(min)  V(max)   (${label})
${wave(rise, vfix)}`;
const vccOf = c => c.vcc;
const model = (name, type, waves) => `[Model] ${name}
Model_type ${type}
Polarity Non-Inverting
Enable Active-High
Vinl = 0.8
Vinh = 2.0
Vmeas = 1.65
Vref = 0
Rref = 1k
Cref = 0
| variable   typ      min      max
C_comp       3.0pF    3.5pF    2.5pF
[Voltage Range]  3.3  3.0  3.6
[Temperature Range]  25  85  0
[Pulldown]
| V  I(typ)  I(min)  I(max)
${ivRows(pd, -3.3, 6.6, 34)}
[Pullup]
| Vcc-V  I(typ)  I(min)  I(max)
${ivRows(pu, -3.3, 6.6, 34)}
[GND Clamp]
${ivRows((c, v) => clamp(v), -3.3, 0, 12)}
[POWER Clamp]
| Vcc-V  I(typ)  I(min)  I(max)
${ivRows((c, v) => -clamp(v), -3.3, 0, 12)}
[Ramp]
| variable  typ          min          max
dV/dt_r     1.98/0.433n  1.80/0.577n  2.16/0.325n
dV/dt_f     1.98/0.433n  1.80/0.577n  2.16/0.325n
R_load = 50
${waves ? [wf(true, 0, "50 ohm to GND"), wf(true, vccOf, "50 ohm to VCC"), wf(false, 0, "50 ohm to GND"), wf(false, vccOf, "50 ohm to VCC")].join("\n") : ""}`;
const text = `[IBIS Ver]   5.1
| Atrium SI test fixture. Synthetic data generated by tests/fixtures/si/make-demo-ibis.cjs.
| Released under CC0 1.0: no rights reserved. Not a model of any real part.
[File Name]  atrium-demo.ibs
[File Rev]   1.0
[Date]       2026-11-19
[Source]     Closed-form device (tanh-saturated 40 ohm driver, raised-cosine edge).
[Notes]      Pin 1 uses two-waveform switching data; pin 2 uses [Ramp] only;
             pin 6 is a model selector. Corners: min = slow/weak, max = fast/strong.
[Disclaimer] For testing only.
[Copyright]  CC0 1.0
|
[Component]     ATRIUM_DEMO
[Manufacturer]  Atrium test data
[Package]
| variable  typ      min      max
R_pkg       0.20     0.15     0.25
L_pkg       2.0nH    1.5nH    2.5nH
C_pkg       0.40pF   0.30pF   0.50pF
[Pin]  signal_name  model_name  R_pin  L_pin  C_pin
1      DQ0          DQ_IO       0.25   2.2nH  0.45pF
2      CLK          CLK_OUT
3      RX           IN_RX
4      VDD          POWER
5      VSS          GND
6      SEL0         DQ_SEL
7      NC1          NC
|
[Model Selector] DQ_SEL
DQ_IO     Full drive (40 ohm), two-waveform data
CLK_OUT   Ramp-only drive
|
${model("DQ_IO", "I/O", true)}
|
${model("CLK_OUT", "Output", false)}
|
[Model] IN_RX
Model_type Input
Vinl = 0.8
Vinh = 2.0
C_comp  2.0pF  2.4pF  1.6pF
[Voltage Range]  3.3  3.0  3.6
[GND Clamp]
${ivRows((c, v) => clamp(v), -3.3, 0, 12)}
[POWER Clamp]
${ivRows((c, v) => -clamp(v), -3.3, 0, 12)}
|
[End]
`;
print(text);
